CREATE    PROCEDURE [synapse_fo].[usp_Update_inventlocation]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-06-06 15:03:21
	Description: Update stored procedure for inventlocation from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ActivityType_RU] = stg.[ActivityType_RU],
		tgt.[AllowLaborStandards] = stg.[AllowLaborStandards],
		tgt.[AllowMarkingReservationRemoval] = stg.[AllowMarkingReservationRemoval],
		tgt.[AutoUpdateShipment] = stg.[AutoUpdateShipment],
		tgt.[BranchNumber] = stg.[BranchNumber],
		tgt.[CONSOLIDATESHIPATRTW] = stg.[CONSOLIDATESHIPATRTW],
		tgt.[CREATEDBY] = stg.[CREATEDBY],
		tgt.[CREATEDDATETIME] = stg.[CREATEDDATETIME],
		tgt.[CustAccount_BR] = stg.[CustAccount_BR],
		tgt.[CustAccount_HU] = stg.[CustAccount_HU],
		tgt.[CycleCountAllowPalletMove] = stg.[CycleCountAllowPalletMove],
		tgt.[DataAreaId] = stg.[DataAreaId],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DecrementLoadLine] = stg.[DecrementLoadLine],
		tgt.[DefaultContainerTypeCode] = stg.[DefaultContainerTypeCode],
		tgt.[DefaultFinalShipmentLocation] = stg.[DefaultFinalShipmentLocation],
