		tgt.[EMPTYPALLETLOCATION] = stg.[EMPTYPALLETLOCATION],
		tgt.[EnableQualityManagement] = stg.[EnableQualityManagement],
		--tgt.[FileName] = stg.[FileName],
		tgt.[FSHStore] = stg.[FSHStore],
		tgt.[HMIMDomesticLanguage] = stg.[HMIMDomesticLanguage],
		tgt.[HMIMExportLanguage] = stg.[HMIMExportLanguage],
		tgt.[InventCountingGroup_BR] = stg.[InventCountingGroup_BR],
		tgt.[InventLocationId] = stg.[InventLocationId],
