		tgt.[InventLocationIdReqMain] = stg.[InventLocationIdReqMain],
		tgt.[InventLocationIdTransit] = stg.[InventLocationIdTransit],
		tgt.[InventLocationLevel] = stg.[InventLocationLevel],
		tgt.[InventLocationType] = stg.[InventLocationType],
		tgt.[InventProfileId_RU] = stg.[InventProfileId_RU],
		tgt.[InventProfileType_RU] = stg.[InventProfileType_RU],
		tgt.[InventSiteId] = stg.[InventSiteId],
		tgt.[InventUseDefaultProductionLocationForFormulaBOM] = stg.[InventUseDefaultProductionLocationForFormulaBOM],
		tgt.[ITMInventLocationIdGIT] = stg.[ITMInventLocationIdGIT],
		tgt.[ITMInventLocationIdUnder] = stg.[ITMInventLocationIdUnder],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		tgt.[LoadReleaseReservationPolicy] = stg.[LoadReleaseReservationPolicy],
		--tgt.[LSN] = stg.[LSN],
		tgt.[Manual] = stg.[Manual],
		tgt.[MAXPICKINGROUTETIME] = stg.[MAXPICKINGROUTETIME],
		tgt.[MAXPICKINGROUTEVOLUME] = stg.[MAXPICKINGROUTEVOLUME],
		tgt.[MODIFIEDBY] = stg.[MODIFIEDBY],
		tgt.[MODIFIEDDATETIME] = stg.[MODIFIEDDATETIME],
		tgt.[Name] = stg.[Name],
