		tgt.[PICKINGLINETIME] = stg.[PICKINGLINETIME],
		tgt.[PrintBOLBeforeShipConfirm] = stg.[PrintBOLBeforeShipConfirm],
		tgt.[ProdReserveOnlyWhse] = stg.[ProdReserveOnlyWhse],
		tgt.[RAFPostingMethod] = stg.[RAFPostingMethod],
		tgt.[RBODefaultInventProfileId_RU] = stg.[RBODefaultInventProfileId_RU],
		tgt.[RBODefaultWMSLocationId] = stg.[RBODefaultWMSLocationId],
		tgt.[RBODEFAULTWMSPALLETID] = stg.[RBODEFAULTWMSPALLETID],
