		tgt.[RetailInventNegFinancial] = stg.[RetailInventNegFinancial],
		tgt.[RetailInventNegPhysical] = stg.[RetailInventNegPhysical],
		tgt.[RetailWeightEx1] = stg.[RetailWeightEx1],
		tgt.[RetailWMSLocationIdDefaultReturn] = stg.[RetailWMSLocationIdDefaultReturn],
		tgt.[RETAILWMSPALLETIDDEFAULTRETURN] = stg.[RETAILWMSPALLETIDDEFAULTRETURN],
		--tgt.[SysRowId] = stg.[SysRowId],
		--tgt.[SYSSHARINGDATAAREAID] = stg.[SYSSHARINGDATAAREAID],
		tgt.[UniqueCheckDigits] = stg.[UniqueCheckDigits],
		tgt.[USEWMSORDERS] = stg.[USEWMSORDERS],
		tgt.[VendAccount] = stg.[VendAccount],
		tgt.[VendAccountCustom_RU] = stg.[VendAccountCustom_RU],
		tgt.[WarehouseAutoReleaseReservation] = stg.[WarehouseAutoReleaseReservation],
		tgt.[WHSEnabled] = stg.[WHSEnabled],
		tgt.[WHSProdOrderBackflushMustUseReservedQty] = stg.[WHSProdOrderBackflushMustUseReservedQty],
		tgt.[WHSRawMaterialPolicy] = stg.[WHSRawMaterialPolicy],
		tgt.[WMSAisleNameActive] = stg.[WMSAisleNameActive],
		tgt.[WMSLevelFormat] = stg.[WMSLevelFormat],
		tgt.[WMSLevelNameActive] = stg.[WMSLevelNameActive],
		tgt.[WMSlocationIdDefaultIssue] = stg.[WMSlocationIdDefaultIssue],
		tgt.[WMSLocationIdDefaultReceipt] = stg.[WMSLocationIdDefaultReceipt],
		tgt.[WMSLocationIdGoodsInRoute_RU] = stg.[WMSLocationIdGoodsInRoute_RU],
		tgt.[WMSPositionFormat] = stg.[WMSPositionFormat],
		tgt.[WMSPositionNameActive] = stg.[WMSPositionNameActive],
		tgt.[WMSRackFormat] = stg.[WMSRackFormat],
		tgt.[WMSRackNameActive] = stg.[WMSRackNameActive],
		tgt.[WorkProcessingPolicyName] = stg.[WorkProcessingPolicyName]
	 FROM [synapse_fo].[INVENTLOCATION] tgt
		INNER JOIN [staging_fo].[INVENTLOCATION] stg
			ON  stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[InventLocationId] = tgt.[InventLocationId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
		
